===
{
  "watches": [
    {
      "name": "Core CRUD",
      "scenarios": [
        "todo-management.feature:Create a new todo",
        "todo-management.feature:Reject empty or whitespace-only todos",
        "todo-management.feature:Toggle a todo as completed",
        "todo-management.feature:Toggle a completed todo back to active",
        "todo-management.feature:Delete a todo"
      ]
    },
    {
      "name": "Editing",
      "scenarios": [
        "todo-management.feature:Activate editing mode on double-click",
        "todo-management.feature:Save edited todo on Enter",
        "todo-management.feature:Save edited todo on blur",
        "todo-management.feature:Destroy todo on empty edit",
        "todo-management.feature:Discard edit on Escape"
      ]
    },
    {
      "name": "Bulk Operations & Layout",
      "scenarios": [
        "todo-management.feature:Mark all todos as complete",
        "todo-management.feature:Unmark all todos when toggle-all is unchecked",
        "todo-management.feature:Hide main and footer when no todos",
        "todo-management.feature:Show main and footer when todos exist",
        "todo-management.feature:Clear completed todos",
        "todo-management.feature:Toggle-all checkbox reflects individual toggles"
      ]
    },
    {
      "name": "Counters",
      "scenarios": [
        "todo-management.feature:Pluralized item count - zero items",
        "todo-management.feature:Pluralized item count - one item",
        "todo-management.feature:Pluralized item count - two items"
      ]
    },
    {
      "name": "Routing",
      "scenarios": [
        "routing.feature:Default route is All",
        "routing.feature:Active filter shows only active todos",
        "routing.feature:Completed filter shows only completed todos",
        "routing.feature:Toggle in filtered view hides item"
      ]
    },
    {
      "name": "Persistence",
      "scenarios": [
        "routing.feature:Persist todos to localStorage",
        "routing.feature:Restore todos from localStorage on reload",
        "routing.feature:Active filter persists on reload"
      ]
    }
  ]
}

const { Given, When, Then } = require('@cucumber/cucumber');
const assert = require('assert');

// Background
Given('the app is loaded cleanly', function () {
  this.loadApp();
});

// --- Create ---

Given('no todos exist', function () {
  const items = this.getTodoItems();
  assert.strictEqual(items.length, 0, 'Expected no todo items');
});

Given('a todo {string} exists', function (title) {
  const input = this.querySelector('.new-todo');
  input.value = title;
  this.triggerKeyEvent(input, 'Enter', 13);
});

Given('a completed todo {string} exists', function (title) {
  const input = this.querySelector('.new-todo');
  input.value = title;
  this.triggerKeyEvent(input, 'Enter', 13);
  const item = this.getTodoByTitle(title);
  assert.ok(item, 'Todo "' + title + '" not found');
  const toggle = item.querySelector('.toggle');
  toggle.checked = true;
  toggle.dispatchEvent(new this.window.Event('change', { bubbles: true }));
});

Given('todos {string} and {string} exist', function (title1, title2) {
  const input = this.querySelector('.new-todo');
  input.value = title1;
  this.triggerKeyEvent(input, 'Enter', 13);
  input.value = title2;
  this.triggerKeyEvent(input, 'Enter', 13);
});

Given('a completed todo {string} exists and an active todo {string} exists', function (completed, active) {
  const input = this.querySelector('.new-todo');
  input.value = completed;
  this.triggerKeyEvent(input, 'Enter', 13);
  const item = this.getTodoByTitle(completed);
  assert.ok(item, 'Todo "' + completed + '" not found');
  const toggle = item.querySelector('.toggle');
  toggle.checked = true;
  toggle.dispatchEvent(new this.window.Event('change', { bubbles: true }));
  input.value = active;
  this.triggerKeyEvent(input, 'Enter', 13);
});

Given('all todos are marked completed', function () {
  const items = this.getTodoItems();
  for (let i = 0; i < items.length; i++) {
    const toggle = items[i].querySelector('.toggle');
    if (!toggle.checked) {
      toggle.checked = true;
      toggle.dispatchEvent(new this.window.Event('change', { bubbles: true }));
    }
  }
});

Given('localStorage contains a todo {string}', function (title) {
  const todos = JSON.parse(this.localStorage.getItem('todos-vanillajs') || '[]');
  todos.push({ id: Date.now(), title: title, completed: false });
  this.localStorage.setItem('todos-vanillajs', JSON.stringify(todos));
});

Given('the {string} filter is selected', function (filter) {
  const map = { Active: '#/active', Completed: '#/completed', All: '#/' };
  const hash = map[filter] || '#/';
  this.dispatchHashChange(hash);
});

// --- When ---

When('I type {string} into the new-todo input and press Enter', function (value) {
  const input = this.querySelector('.new-todo');
  input.value = value;
  this.triggerKeyEvent(input, 'Enter', 13);
});

When('I click the toggle checkbox on the todo', function () {
  const items = this.getTodoItems();
  assert.ok(items.length > 0, 'No todo items');
  const toggle = items[0].querySelector('.toggle');
  toggle.checked = !toggle.checked;
  toggle.dispatchEvent(new this.window.Event('change', { bubbles: true }));
});

When('I click the destroy button on the todo', function () {
  const items = this.getTodoItems();
  assert.ok(items.length > 0, 'No todo items');
  const destroy = items[0].querySelector('.destroy');
  destroy.click();
});

When('I double-click the label of the todo', function () {
  const items = this.getTodoItems();
  assert.ok(items.length > 0, 'No todo items');
  const label = items[0].querySelector('label');
  label.dispatchEvent(new this.window.MouseEvent('dblclick', { bubbles: true }));
});

When('I double-click the label and change the value to {string} and press Enter', function (value) {
  const items = this.getTodoItems();
  assert.ok(items.length > 0, 'No todo items');
  const label = items[0].querySelector('label');
  label.dispatchEvent(new this.window.MouseEvent('dblclick', { bubbles: true }));
  const editInput = items[0].querySelector('.edit');
  editInput.value = value;
  this.triggerKeyEvent(editInput, 'Enter', 13);
});

When('I double-click the label and change the value to {string} and blur the input', function (value) {
  const items = this.getTodoItems();
  assert.ok(items.length > 0, 'No todo items');
  const label = items[0].querySelector('label');
  label.dispatchEvent(new this.window.MouseEvent('dblclick', { bubbles: true }));
  const editInput = items[0].querySelector('.edit');
  editInput.value = value;
  editInput.dispatchEvent(new this.window.FocusEvent('blur', { bubbles: true }));
});

When('I double-click the label and clear the input and press Enter', function () {
  const items = this.getTodoItems();
  assert.ok(items.length > 0, 'No todo items');
  const label = items[0].querySelector('label');
  label.dispatchEvent(new this.window.MouseEvent('dblclick', { bubbles: true }));
  const editInput = items[0].querySelector('.edit');
  editInput.value = '';
  this.triggerKeyEvent(editInput, 'Enter', 13);
});

When('I double-click the label and press Escape', function () {
  const items = this.getTodoItems();
  assert.ok(items.length > 0, 'No todo items');
  const label = items[0].querySelector('label');
  label.dispatchEvent(new this.window.MouseEvent('dblclick', { bubbles: true }));
  const editInput = items[0].querySelector('.edit');
  this.triggerKeyEvent(editInput, 'Escape', 27);
});

When('I click the toggle-all checkbox', function () {
  const toggleAll = this.querySelector('#toggle-all');
  toggleAll.checked = !toggleAll.checked;
  toggleAll.dispatchEvent(new this.window.Event('change', { bubbles: true }));
});

When('I click the clear-completed button', function () {
  const btn = this.querySelector('.clear-completed');
  btn.click();
});

When('the app loads', function () {
  this.dispatchHashChange('#/');
});

When('I click the {string} filter link', function (filter) {
  const links = this.querySelectorAll('.filters a');
  for (let i = 0; i < links.length; i++) {
    if (links[i].textContent.trim() === filter) {
      links[i].click();
      return;
    }
  }
  assert.fail('Filter "' + filter + '" not found');
});

When('the app triggers a save', function () {
  if (typeof this.app.save === 'function') {
    this.app.save();
  }
});

When('the app reloads', function () {
  const todosJson = this.localStorage.getItem('todos-vanillajs');
  const filterHash = this.window.location.hash;
  this.loadApp();
  if (todosJson) {
    this.localStorage.setItem('todos-vanillajs', todosJson);
  }
  this.window.location.hash = filterHash;
  if (typeof this.app.loadTodos === 'function') {
    this.app.loadTodos();
  }
  if (typeof this.app.onHashChange === 'function') {
    this.app.onHashChange(this.window.location.hash);
  }
});

When('I click the {string} filter', function (filter) {
  const links = this.querySelectorAll('.filters a');
  for (let i = 0; i < links.length; i++) {
    if (links[i].textContent.trim() === filter) {
      links[i].click();
      return;
    }
  }
  assert.fail('Filter "' + filter + '" not found');
});

When('I mark {string} as completed', function (title) {
  const item = this.getTodoByTitle(title);
  assert.ok(item, 'Todo "' + title + '" not found');
  const toggle = item.querySelector('.toggle');
  toggle.checked = true;
  toggle.dispatchEvent(new this.window.Event('change', { bubbles: true }));
});

// --- Then ---

Then('a todo item with title {string} appears in the list', function (title) {
  const item = this.getTodoByTitle(title);
  assert.ok(item, 'Todo "' + title + '" not found in list');
});

Then('the new-todo input is cleared', function () {
  const input = this.querySelector('.new-todo');
  assert.strictEqual(input.value, '', 'New todo input was not cleared');
});

Then('no todo item is added to the list', function () {
  const items = this.getTodoItems();
  assert.strictEqual(items.length, 0, 'Expected no todo items but found some');
});

Then('the todo list remains empty', function () {
  const items = this.getTodoItems();
  assert.strictEqual(items.length, 0, 'Expected list to remain empty');
});

Then('the todo item has the class {string}', function (className) {
  const items = this.getTodoItems();
  assert.ok(items.length > 0, 'No todo items');
  assert.ok(items[0].classList.contains(className), 'Item missing class "' + className + '"');
});

Then('its toggle checkbox becomes checked', function () {
  const items = this.getTodoItems();
  assert.ok(items.length > 0, 'No todo items');
  const toggle = items[0].querySelector('.toggle');
  assert.ok(toggle.checked, 'Toggle checkbox is not checked');
});

Then('the todo item does not have the class {string}', function (className) {
  const items = this.getTodoItems();
  assert.ok(items.length > 0, 'No todo items');
  assert.ok(!items[0].classList.contains(className), 'Item should not have class "' + className + '"');
});

Then('its toggle checkbox is unchecked', function () {
  const items = this.getTodoItems();
  assert.ok(items.length > 0, 'No todo items');
  const toggle = items[0].querySelector('.toggle');
  assert.ok(!toggle.checked, 'Toggle checkbox is checked');
});

Then('the todo {string} is removed from the list', function (title) {
  const item = this.getTodoByTitle(title);
  assert.strictEqual(item, null, 'Todo "' + title + '" was not removed');
});

Then('the todo title is {string}', function (expected) {
  const items = this.getTodoItems();
  assert.ok(items.length > 0, 'No todo items');
  const label = items[0].querySelector('label');
  assert.strictEqual(label.textContent.trim(), expected, 'Title mismatch');
});

Then('the todo title remains {string}', function (expected) {
  const items = this.getTodoItems();
  assert.ok(items.length > 0, 'No todo items');
  const label = items[0].querySelector('label');
  assert.strictEqual(label.textContent.trim(), expected, 'Title mismatch');
});

Then('the edit input is focused', function () {
  const items = this.getTodoItems();
  assert.ok(items.length > 0, 'No todo items');
  const edit = items[0].querySelector('.edit');
  assert.ok(edit === this.document.activeElement, 'Edit input is not focused');
});

Then('all todos have the class {string}', function (className) {
  const items = this.getTodoItems();
  for (let i = 0; i < items.length; i++) {
    assert.ok(items[i].classList.contains(className), 'Item ' + i + ' missing class "' + className + '"');
  }
});

Then('no todos have the class {string}', function (className) {
  const items = this.getTodoItems();
  for (let i = 0; i < items.length; i++) {
    assert.ok(!items[i].classList.contains(className), 'Item ' + i + ' should not have class "' + className + '"');
  }
});

Then(/^the ([#a-z]+) section is hidden$/, function (sectionId) {
  const section = this.querySelector(sectionId);
  const style = this.window.getComputedStyle(section);
  assert.strictEqual(style.display, 'none', 'Section "' + sectionId + '" should be hidden');
});

Then(/^the ([#a-z]+) section is visible$/, function (sectionId) {
  const section = this.querySelector(sectionId);
  const style = this.window.getComputedStyle(section);
  assert.notStrictEqual(style.display, 'none', 'Section "' + sectionId + '" should be visible');
});

Then('only the todo {string} remains in the list', function (title) {
  const items = this.getTodoItems();
  assert.strictEqual(items.length, 1, 'Expected 1 item, found ' + items.length);
  const label = items[0].querySelector('label');
  assert.strictEqual(label.textContent.trim(), title, 'Unexpected title');
});

Then('the clear-completed button is hidden', function () {
  const btn = this.querySelector('.clear-completed');
  const style = this.window.getComputedStyle(btn);
  assert.strictEqual(style.display, 'none', 'Clear-completed button should be hidden');
});

Then('the todo-count shows {string}', function (expected) {
  const el = this.querySelector('.todo-count');
  assert.ok(el, 'todo-count element not found');
  assert.strictEqual(el.textContent.trim(), expected, 'todo-count mismatch');
});

Then('the toggle-all checkbox is unchecked', function () {
  const toggleAll = this.querySelector('#toggle-all');
  assert.ok(!toggleAll.checked, 'Toggle-all should be unchecked');
});

Then('the toggle-all checkbox is checked', function () {
  const toggleAll = this.querySelector('#toggle-all');
  assert.ok(toggleAll.checked, 'Toggle-all should be checked');
});

// --- Routing ---

Then('the {string} filter link has the class {string}', function (filterText, className) {
  const links = this.querySelectorAll('.filters a');
  for (let i = 0; i < links.length; i++) {
    if (links[i].textContent.trim() === filterText) {
      assert.ok(links[i].classList.contains(className), 'Filter "' + filterText + '" missing class "' + className + '"');
      return;
    }
  }
  assert.fail('Filter "' + filterText + '" not found');
});

Then('all todos are shown', function () {
  const items = this.getTodoItems();
  for (let i = 0; i < items.length; i++) {
    assert.notStrictEqual(items[i].style.display, 'none', 'A todo is hidden but should be shown');
  }
});

Then('only the active todo {string} is visible in the list', function (title) {
  const visible = this.getVisibleTodos();
  assert.strictEqual(visible.length, 1, 'Expected 1 visible todo, found ' + visible.length);
  const label = visible[0].querySelector('label');
  assert.strictEqual(label.textContent.trim(), title, 'Unexpected visible todo');
});

Then('only the completed todo {string} is visible in the list', function (title) {
  const visible = this.getVisibleTodos();
  assert.strictEqual(visible.length, 1, 'Expected 1 visible todo, found ' + visible.length);
  const label = visible[0].querySelector('label');
  assert.strictEqual(label.textContent.trim(), title, 'Unexpected visible todo');
});

Then('localStorage has a key matching {string} with an entry for {string}', function (keyPattern, title) {
  const keys = Object.keys(this.localStorage);
  const matchingKey = keys.find(function(k) { return k.startsWith('todos-'); });
  assert.ok(matchingKey, 'No localStorage key matching "' + keyPattern + '"');
  const data = JSON.parse(this.localStorage.getItem(matchingKey));
  assert.ok(Array.isArray(data), 'localStorage data is not an array');
  const found = data.find(function(t) { return t.title === title; });
  assert.ok(found, 'Todo "' + title + '" not found in localStorage');
});

Then('the todo {string} appears in the list', function (title) {
  const item = this.getTodoByTitle(title);
  assert.ok(item, 'Todo "' + title + '" not found in list after reload');
});

Then('the {string} filter link still has the class {string}', function (filterText, className) {
  const links = this.querySelectorAll('.filters a');
  for (let i = 0; i < links.length; i++) {
    if (links[i].textContent.trim() === filterText) {
      assert.ok(links[i].classList.contains(className), 'Filter "' + filterText + '" should still have class "' + className + '"');
      return;
    }
  }
  assert.fail('Filter "' + filterText + '" not found');
});

Then('{string} is hidden from the list', function (title) {
  const item = this.getTodoByTitle(title);
  if (item) {
    assert.strictEqual(item.style.display, 'none', 'Todo "' + title + '" should be hidden');
  }
});

const { setWorldConstructor, setDefaultTimeout } = require('@cucumber/cucumber');
const { Window } = require('happy-dom');
const fs = require('fs');
const path = require('path');

setDefaultTimeout(10000);

function TodoWorld() {
  this.window = null;
  this.document = null;
  this.localStorage = null;
  this.app = null;

  this.loadApp = function () {
    const htmlPath = path.resolve(__dirname, '../../index.html');
    const html = fs.readFileSync(htmlPath, 'utf8');
    const win = new Window({ url: 'http://localhost/#/' });
    win.document.write(html);
    this.window = win;
    this.document = win.document;
    this.localStorage = win.localStorage;
    this.localStorage.clear();
    global.window = win;
    global.document = win.document;
    global.localStorage = win.localStorage;
    global.location = win.location;
    global.setTimeout = win.setTimeout.bind(win);
    global.clearTimeout = win.clearTimeout.bind(win);
    global.Event = win.Event;
    global.KeyboardEvent = win.KeyboardEvent;
    global.FocusEvent = win.FocusEvent;
    global.MouseEvent = win.MouseEvent;
    global.HTMLLIElement = win.HTMLLIElement;
    global.HTMLInputElement = win.HTMLInputElement;

    // Load the app script
    const appJs = fs.readFileSync(path.resolve(__dirname, '../../js/app.js'), 'utf8');
    win.eval(appJs);
    this.app = win.app;
  };

  this.querySelector = function (selector) {
    return this.document.querySelector(selector);
  };

  this.querySelectorAll = function (selector) {
    return this.document.querySelectorAll(selector);
  };

  this.getTodoItems = function () {
    return this.querySelectorAll('.todo-list li');
  };

  this.getTodoByTitle = function (title) {
    const items = this.getTodoItems();
    for (let i = 0; i < items.length; i++) {
      const label = items[i].querySelector('label');
      if (label && label.textContent.trim() === title) {
        return items[i];
      }
    }
    return null;
  };

  this.getVisibleTodos = function () {
    const all = this.getTodoItems();
    const result = [];
    for (let i = 0; i < all.length; i++) {
      if (all[i].style.display !== 'none') {
        result.push(all[i]);
      }
    }
    return result;
  };

  this.dispatchHashChange = function (hash) {
    this.window.location.hash = hash;
    if (typeof this.app.onHashChange === 'function') {
      this.app.onHashChange(hash);
    }
  };

  this.triggerEvent = function (element, eventType, options) {
    const evt = new this.window.Event(eventType, options || {});
    element.dispatchEvent(evt);
  };

  this.triggerKeyEvent = function (element, key, keyCode) {
    const evt = new this.window.KeyboardEvent('keydown', {
      key: key,
      keyCode: keyCode,
      which: keyCode,
      bubbles: true
    });
    element.dispatchEvent(evt);
  };
}

setWorldConstructor(TodoWorld);

(function (window) {
  'use strict';

  var ENTER_KEY = 13;
  var ESCAPE_KEY = 27;
  var STORAGE_KEY = 'todos-vanillajs';

  var todos = [];
  var filter = 'all';

  /**
   * @planks("the app is loaded cleanly")
   */
  function TodoApp() {
    this.loadTodos();
    this.bindEvents();
    this.render();
  }

  /**
   * @planks("localStorage has a key matching {string} with an entry for {string}")
   */
  TodoApp.prototype.save = function () {
    window.localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
  };

  /**
   * @planks("localStorage contains a todo {string}")
   * @planks("the app reloads")
   */
  TodoApp.prototype.loadTodos = function () {
    try {
      var stored = window.localStorage.getItem(STORAGE_KEY);
      todos = stored ? JSON.parse(stored) : [];
    } catch (e) {
      todos = [];
    }
  };

  TodoApp.prototype.generateId = function () {
    return Date.now() + Math.random();
  };

  /**
   * @planks("I type {string} into the new-todo input and press Enter")
   * @planks("I type {string} into the new-todo input and press Enter")
   */
  TodoApp.prototype.addTodo = function (title) {
    var trimmed = title.trim();
    if (trimmed === '') {
      return false;
    }
    todos.push({
      id: this.generateId(),
      title: trimmed,
      completed: false
    });
    this.save();
    this.render();
    return true;
  };

  /**
   * @planks("I click the destroy button on the todo")
   * @planks("I double-click the label and clear the input and press Enter")
   */
  TodoApp.prototype.removeTodo = function (id) {
    todos = todos.filter(function (t) { return t.id !== id; });
    this.save();
    this.render();
  };

  /**
   * @planks("I click the toggle checkbox on the todo")
   * @planks("I click the toggle checkbox on the todo")
   */
  TodoApp.prototype.toggleTodo = function (id) {
    todos = todos.map(function (t) {
      if (t.id === id) {
        t.completed = !t.completed;
      }
      return t;
    });
    this.save();
    // Update DOM in-place to preserve element identity across the interaction
    var todoList = document.querySelector('.todo-list');
    var li = todoList ? todoList.querySelector('li[data-id="' + id + '"]') : null;
    if (li) {
      var todo = todos.find(function (t) { return t.id === id; });
      if (todo.completed) {
        li.classList.add('completed');
      } else {
        li.classList.remove('completed');
      }
      var checkbox = li.querySelector('.toggle');
      if (checkbox) {
        checkbox.checked = todo.completed;
      }
    }
    this.renderUI();
  };

  /**
   * @planks("I click the toggle-all checkbox")
   * @planks("I click the toggle-all checkbox")
   * @planks("I mark {string} as completed")
   */
  TodoApp.prototype.toggleAll = function (completed) {
    todos = todos.map(function (t) {
      t.completed = completed;
      return t;
    });
    this.save();
    // Update DOM in-place to preserve element identity
    var todoList = document.querySelector('.todo-list');
    if (todoList) {
      var items = todoList.querySelectorAll('li');
      Array.prototype.forEach.call(items, function (li) {
        if (completed) {
          li.classList.add('completed');
        } else {
          li.classList.remove('completed');
        }
        var checkbox = li.querySelector('.toggle');
        if (checkbox) {
          checkbox.checked = completed;
        }
      });
    }
    this.renderUI();
  };

  /**
   * @planks("I click the clear-completed button")
   */
  TodoApp.prototype.clearCompleted = function () {
    todos = todos.filter(function (t) { return !t.completed; });
    this.save();
    this.render();
  };

  /**
   * @planks("I double-click the label and change the value to {string} and press Enter")
   * @planks("I double-click the label and change the value to {string} and blur the input")
   * @planks("I double-click the label and clear the input and press Enter")
   */
  TodoApp.prototype.updateTodo = function (id, title) {
    var trimmed = title.trim();
    if (trimmed === '') {
      this.removeTodo(id);
      return;
    }
    todos = todos.map(function (t) {
      if (t.id === id) {
        t.title = trimmed;
      }
      return t;
    });
    this.save();
    this.render();
  };

  /**
